from typing import Dict, List, Tuple
import heapq

def shortest_path(graph: Dict[str, List[Tuple[str, int]]], source: str, target: str) -> Tuple[float, List[str]]:

    def find(parent: Dict[str, str], node: str) -> str:
        if parent[node] == node:
            return node
        parent[node] = find(parent, parent[node])
        return parent[node]

    def union(parent: Dict[str, str], rank: Dict[str, int], node1: str, node2: str):
        root1 = find(parent, node1)
        root2 = find(parent, node2)
        if root1 != root2:
            if rank[root1] > rank[root2]:
                parent[root2] = root1
            elif rank[root1] < rank[root2]:
                parent[root1] = root2
            else:
                parent[root2] = root1
                rank[root1] += 1

    def kruskal(graph: Dict[str, List[Tuple[str, int]]]) -> Tuple[List[Tuple[str, str, int]], Dict[str, str], Dict[str, int]]:
        parent = {}
        rank = {}
        edges = []
        for node, neighbors in graph.items():
            for neighbor, weight in neighbors:
                edges.append((weight, node, neighbor))
                union(parent, rank, node, neighbor)
        heapq.heapify(edges)
        mst = []
        for weight, node, neighbor in edges:
            if find(parent, node) != find(parent, neighbor):
                mst.append((node, neighbor, weight))
                union(parent, rank, node, neighbor)
        return (mst, parent, rank)

    def find_path(parent: Dict[str, str], nodes: List[str]) -> List[str]:
        path = []
        for node in nodes:
            path.append(node)
            parent_node = parent[node]
            while parent_node != node:
                path.append(parent_node)
                parent_node = parent[parent_node]
        return path
    mst, parent, rank = kruskal(graph)
    visited = {source}
    distance = float('inf')
    path = []
    for weight, node1, node2 in mst:
        if node1 == source and node2 == target:
            distance = weight
            path = [source, target]
            break
        elif node1 == source or node2 == source:
            visited.add(node1)
            visited.add(node2)
            weight_sum = weight
            path = find_path(parent, [node1, node2])
            if target in visited:
                distance = weight_sum
                path = [source] + path[1:]
                break
    if target not in visited:
        return (float('inf'), None)
    return (distance, path)

import heapq

def heuristic(node, target):
    return abs(node[0] - target[0]) + abs(node[1] - target[1])

def a_star_search(graph, source, target):
    queue = [(0, [source])]
    visited = set()
    while queue:
        cost, path = heapq.heappop(queue)
        current_node = path[-1]
        if current_node == target:
            return (cost, path)
        if current_node in visited:
            continue
        visited.add(current_node)
        for neighbor, weight in graph.get(current_node, []):
            total_cost = cost + weight + heuristic(neighbor, target)
            new_path = list(path)
            new_path.append(neighbor)
            heapq.heappush(queue, (total_cost, new_path))
    return (float('inf'), None)

def shortest_path(graph, source, target):
    result = a_star_search(graph, source, target)
    return result
