import math

def shortest_path(graph, source, target):

    def dijkstra(graph, start):
        priority_queue = [(0, start)]
        distance = {node: math.inf for node in graph}
        distance[start] = 0
        visited = set()
        while priority_queue:
            current_distance, current_node = heappop(priority_queue)
            if current_node in visited:
                continue
            visited.add(current_node)
            for neighbor, weight in graph[current_node]:
                distance_to_neighbor = current_distance + weight
                if distance_to_neighbor < distance[neighbor]:
                    distance[neighbor] = distance_to_neighbor
                    heappush(priority_queue, (distance_to_neighbor, neighbor))
        return distance

    def add_self_loops(graph):
        for node in graph:
            graph[node].append((node, 0))
        return graph

    def add_identity_edges(graph, distance):
        identity_graph = defaultdict(list)
        for node, edges in graph.items():
            for neighbor, weight in edges:
                new_weight = distance[node] + distance[neighbor]
                identity_graph[node].append((neighbor, new_weight))
        return identity_graph

    def preprocess(graph):
        distance_from_source = dijkstra(graph, '0')
        graph = add_self_loops(graph)
        graph = add_identity_edges(graph, distance_from_source)
        return graph
    processed_graph = preprocess(graph)
    del processed_graph['0']
    return (dijkstra(processed_graph, str(source)), [str(source)])
