def shortest_path(graph, source, target):

    def bellman_ford(graph, source):
        dist = {node: float('inf') for node in graph}
        dist[source] = 0
        for _ in range(len(graph) - 1):
            for u, neighbors in graph.items():
                for v, weight in neighbors:
                    if dist[u] != float('inf') and dist[u] + weight < dist[v]:
                        dist[v] = dist[u] + weight
        for u, neighbors in graph.items():
            for v, weight in neighbors:
                if dist[u] != float('inf') and dist[u] + weight < dist[v]:
                    raise ValueError('Graph contains a negative weight cycle')
        return dist

    def dijkstra(graph, source):
        dist = {node: float('inf') for node in graph}
        dist[source] = 0
        queue = [(0, source)]
        while queue:
            current_distance, u = heapq.heappop(queue)
            if current_distance > dist[u]:
                continue
            for neighbor, weight in graph[u]:
                distance = current_distance + weight
                if distance < dist[neighbor]:
                    dist[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))
        return dist
    transformed_graph = defaultdict(lambda: [(target, 0)])
    for node, neighbors in graph.items():
        for neighbor, weight in neighbors:
            transformed_graph[node][0] += weight
    dist = bellman_ford(transformed_graph, source)
    path = [source]
    current_node = target
    while current_node != source:
        for neighbor, weight in graph[current_node]:
            if dist[neighbor] == dist[current_node] + weight:
                path.append(neighbor)
                current_node = neighbor
                break
    if path[-1] != source:
        return (float('inf'), None)
    else:
        path.reverse()
        return (dist[target], path)
