def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return (float('inf'), None)

    def bfs(graph, start, target):
        queue = [(start, [start])]
        visited = set([start])
        while queue:
            current_node, path = queue.pop(0)
            if current_node == target:
                return path
            for neighbor, _ in graph.get(current_node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))
        return None
    forward_path = bfs(graph, source, target)
    backward_path = bfs(graph, target, source)
    if not forward_path or not backward_path:
        return (float('inf'), None)
    i, j = (0, 0)
    while i < len(forward_path) and j < len(backward_path):
        if forward_path[i] == backward_path[j]:
            return (sum((graph[forward_path[i]][0][1] for forward_path[i], _ in enumerate(forward_path[:i + 1]))) + sum((graph[backward_path[j]][0][1] for backward_path[j], _ in enumerate(backward_path[:j + 1]))), forward_path + backward_path[j:])
        elif forward_path[i] < backward_path[j]:
            i += 1
        else:
            j += 1
    return (float('inf'), None)
