        for _ in range(size):
            path = [source]
            for _ in range(len(graph) - 1):
                neighbors = list(graph[path[-1]])
                neighbor = random.choice(neighbors)
                path.append(neighbor[0])
            population.append(path)
        return population

    def fitness(path):
        total_weight = 0
        for i in range(len(path) - 1):
            total_weight += graph[path[i]][path[i + 1]][1]
        return total_weight

    def mutate(path, mutation_rate):
        if random.random() < mutation_rate:
            index1, index2 = random.sample(range(len(path)), 2)
            path[index1], path[index2] = path[index2], path[index1]
        return path

    def crossover(parent1, parent2):
        index1, index2 = random.sample(range(len(parent1) - 1), 2)
        child = parent1[:index1] + parent2[index1:index2+1] + parent1[index2+1:]
        return child

    def evaluate(population):
        results = []
        for path in population:
            total_weight = fitness(path)
            results.append((total_weight, path))
        return results

    def elitism(population_size, elite_ratio):
        population = sorted(population)[:int(population_size * elite_ratio)]
        return population

    def run_genetic_algorithm(population_size, elite_ratio, mutation_rate, generations):
        best_paths = []
        for _ in range(generations):
            population = generate_population(population_size)
            population = elitism(population_size, elite_ratio)
            for _ in range(population_size - int(population_size * elite_ratio)):
                parent1 = random.choice(population)
                parent2 = random.choice(population)
                child = crossover(parent1, parent2)
                child = mutate(child, mutation_rate)
                population.append(child)
            population = evaluate(population)
            population = sorted(population)[:population_size]
            best_path = min(population, key=lambda x: x[0])
            best_paths.append(best_path)
        return best_paths[-1]

    def reconstruct_path(best_path, graph):
        path = [best_path[1][0]]
        for node in best_path[1][1:]:
            if (path[-1], node) in graph or (node, path[-1]) in graph:
                path.append(node)
        return path

    population_size = 100
    elite_ratio = 0.1
    mutation_rate = 0.01
    generations = 100

    best_path = run_genetic_algorithm(population_size, elite_ratio, mutation_rate, generations)

    if best_path:
        return best_path[0], reconstruct_path(best_path, graph)
    else:
        return float('inf'), None

