def a_star(graph, start, goal, heuristic):
    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {state: float('inf') for state in graph}
    g_score[start] = 0
    f_score = {state: float('inf') for state in graph}
    f_score[start] = heuristic(start, goal)
    while open_set:
        _, current = heapq.heappop(open_set)
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.reverse()
            return (path, g_score[goal])
        for neighbor, weight in graph.get(current, []):
            tentative_g_score = g_score[current] + weight
            if tentative_g_score < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = tentative_g_score + heuristic(neighbor, goal)
                heapq.heappush(open_set, (f_score[neighbor], neighbor))
    return (None, float('inf'))

def bidirectional_a_star(graph, start, goal):
    forward_path, forward_dist = a_star(graph, start, goal, heuristic)
    backward_path, backward_dist = a_star(graph, goal, start, heuristic)
    if forward_path and backward_path:
        i, j = (0, 0)
        while i < len(forward_path) and j < len(backward_path):
            if forward_path[i] == backward_path[j]:
                return (forward_path[i:], min(forward_dist, backward_dist))
            elif forward_path[i] < backward_path[j]:
                i += 1
            else:
                j += 1
    return (None, float('inf'))

