from itertools import product

def find_parent(parent: Dict[int, int], i: int) -> int:
    if parent[i] != i:
        parent[i] = find_parent(parent, parent[i])
    return parent[i]

def union(parent: Dict[int, int], rank: Dict[int, int], x: int, y: int) -> None:
    x_root = find_parent(parent, x)
    y_root = find_parent(parent, y)
    if rank[x_root] < rank[y_root]:
        parent[x_root] = y_root
    elif rank[x_root] > rank[y_root]:
        parent[y_root] = x_root
    else:
        parent[y_root] = x_root
        rank[x_root] += 1

def kruskal_mst(graph: Dict[int, List[Tuple[int, int]]]) -> Tuple[List[Tuple[int, int]], int]:
    parent = {i: i for i in graph}
    rank = {i: 0 for i in graph}
    result = []
    edges = sorted(graph.items(), key=lambda x: x[1], reverse=False)
    for edge in edges:
        u, v, w = (edge[0], edge[1][0][0], edge[1][0][1])
        x = find_parent(parent, u)
        y = find_parent(parent, v)
        if x != y:
            result.append((u, v, w))
            union(parent, rank, x, y)
    return (result, result[-1][2])

def find_shortest_path_dijkstra(graph: Dict[int, List[Tuple[int, int]]], source: int, target: int) -> Tuple[float, List[int]]:
    dist = defaultdict(lambda: defaultdict(lambda: float('inf')))
    dist[source][source] = 0
    for u, v, w in graph[source]:
        dist[source][u] = min(dist[source][u], w)
    for k, u, v, w in product(graph, graph, graph, graph[source]):
        dist[u][v] = min(dist[u][v], dist[u][k] + dist[k][v])
    return (dist[source][target], list(find_path(graph, source, target, dist)))

def find_path(graph: Dict[int, List[Tuple[int, int]]], source: int, target: int, dist: Dict[int, Dict[int, int]]) -> List[int]:
    path = [target]
    while target != source:
        target = min(dist[source].keys(), key=lambda x: dist[source][x]) if source in dist and target in dist[source] else target
        path.append(target)
    path.reverse()
    return path

def shortest_path(graph: Dict[int, List[Tuple[int, int]]], source: int, target: int) -> Tuple[float, List[int]]:
    if source == target:
        return (0, [source])
    mst, mst_weight = kruskal_mst(graph)
    if source not in mst or target not in mst:
        return (float('inf'), None)

