    visited_start = {source: 0}
    visited_end = {target: 0}
    parent_start = {source: None}
    parent_end = {target: None}
    while queue_start and queue_end:
        if len(queue_start) > len(queue_end):
            queue_start, queue_end = (queue_end, queue_start)
            visited_start, visited_end = (visited_end, visited_start)
            parent_start, parent_end = (parent_end, parent_start)
        node = queue_start.popleft()
        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited_start:
                visited_start[neighbor] = visited_start[node] + weight
                parent_start[neighbor] = node
                queue_start.append(neighbor)
        if queue_end and queue_start:
            node = queue_end.popleft()
            for neighbor, weight in graph.get(node, []):
                if neighbor not in visited_end:
                    visited_end[neighbor] = visited_end[node] + weight
                    parent_end[neighbor] = node
                    queue_end.append(neighbor)
    if target not in visited_start or target not in visited_end:
        return (float('inf'), None)
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = parent_start.get(current, None)
