        path = [start]
        visited = {start}
        stack = [(start, [])]
        while stack:
            current, path = stack.pop()
            if current == end:
                return path
            for neighbor, _ in graph.get(current, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append((neighbor, path + [neighbor]))
        return []

