        start_index = random.randint(1, len(parent1) - 2)
        end_index = random.randint(start_index + 1, len(parent1) - 1)
        child = parent1.copy()
        child[start_index:end_index + 1] = parent2[start_index:end_index + 1]
        return (child, parent2[:start_index] + parent2[end_index + 1:])

    def mutation(path: List[int]) -> List[int]:
        if random.random() < 0.1:
            index1 = random.randint(0, len(path) - 1)
            index2 = random.randint(0, len(path) - 1)
            path[index1], path[index2] = (path[index2], path[index1])
        return path
    if source not in graph or target not in graph:
        return (float('inf'), None)

    def distance(path: List[int]) -> float:
        return sum((graph[path[i]][graph[path[i + 1]].index(path[i + 1])] for i in range(len(path) - 1)))

    def evaluate_population(population: List[List[int]]) -> List[Tuple[float, List[int]]]:
        return [(distance(path), path) for path in population]

    def select_parents(population: List[List[int]], fitnesses: List[float]) -> Tuple[List[int], List[int]]:
        selected_indices = random.sample(range(len(population)), 2)
        parent1, parent2 = (population[selected_indices[0]], population[selected_indices[1]])
        if fitnesses[parent1] > fitnesses[parent2]:
            return (parent1, parent2)
        return (parent2, parent1)
