                zero_weight_graph[u][v] = 0
                zero_weight_graph[v][u] = 0
        n = max((max(u, v) for u, v in zero_weight_graph.keys() + zero_weight_graph.values()))
        distances = {u: float('inf') for u in range(n + 1)}
        distances[source] = 0
        for _ in range(n):
            for u in range(n + 1):
                if distances[u] != float('inf'):
                    for v in zero_weight_graph[u]:
                        if distances[u] + zero_weight_graph[u][v] < distances[v]:
                            distances[v] = distances[u] + zero_weight_graph[u][v]
        shortest_paths = {u: [] for u in range(n + 1)}
        for u in range(n + 1):
            for v in zero_weight_graph[u]:
                if distances[u] + zero_weight_graph[u][v] == distances[v]:
                    shortest_paths[v].append((u, v))
        actual_graph = defaultdict(dict)
        for u, neighbors in graph.items():
            for v, weight in neighbors:
                actual_graph[u][v] = weight
                if v in shortest_paths[u]:
                    actual_graph[u][v] += distances[u]
        return actual_graph

    def dijkstra(graph, start, end, n):
        pq = [(0, start, [])]
        visited = set()
        path = []
        while pq:
            cost, u, path = heappop(pq)
            if u not in visited:
                visited.add(u)
                path.append(u)
                if u == end:
                    return (path, cost)
                for v in graph[u]:
                    if v not in visited:
                        heappush(pq, (cost + graph[u][v], v, path[:]))
        return (None, float('inf'))
    preprocessed_graph = preprocess(graph)
    path, cost = dijkstra(preprocessed_graph, source, target, max(preprocessed_graph.keys()) + 1)
    if path is None:
        return (float('inf'), None)
    else:
        return (cost, path)
