import heapq

def shortest_path(graph, source, target):
    def bellman_ford(graph, source):
        # Initialize distances with infinity
        dist = {node: float('inf') for node in graph}
        dist[source] = 0

        # Relax edges |V| - 1 times
        for _ in range(len(graph) - 1):
            for node in graph:
                for neighbor, weight in graph[node]:
                    if dist[node] != float('inf') and dist[node] + weight < dist[neighbor]:
                        dist[neighbor] = dist[node] + weight

        # Check for negative-weight cycles
        for node in graph:
            for neighbor, weight in graph[node]:
                if dist[node] != float('inf') and dist[node] + weight < dist[neighbor]:
                    raise ValueError("Graph contains a negative-weight cycle")

        return dist

    def dijkstra(graph, source):
        # Initialize distances and the priority queue
        dist = {node: float('inf') for node in graph}
        dist[source] = 0
        queue = [(0, source)]

        while queue:
            current_dist, current_node = heapq.heappop(queue)

            # Only explore nodes with a lower distance
            if current_dist != dist[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_dist + weight

                # Relax edge
                if distance < dist[neighbor]:
                    dist[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return dist

    # Step 1: Remove negative weights by adding a small constant to all edges
    constant = 1
    new_graph = defaultdict(list)
    for node, edges in graph.items():
        for neighbor, weight in edges:
            new_graph[node].append((neighbor, weight + constant))

    # Step 2: Run Bellman-Ford on the new graph to get the shortest paths from the new source
    new_source_dist = bellman_ford(new_graph, '0')  # Use any node as the new source

    # Step 3: Run Dijkstra's algorithm to get the shortest paths from each node to the target
    dist = dijkstra(graph, '0')

    # Step 4: Combine the results to get the shortest path from the original source to the target
    # Adjust by subtracting the new source distance
    shortest_path_dist = {target: dist[target] - new_source_dist['0']}
    path = [target]

    while path[-1] != source:
        for node in dist:
            if (dist[path[-1]], path[-1]) == (dist[node] - new_source_dist[node], node):
                path.append(node)
                break

    path = path[::-1]

    # Return the shortest path and its distance
    return (dist[target] - new_source_dist['0'], path) if dist[target] != float('inf') else (float('inf'), None)

