import heapq

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, node):
        if self.parent[node] != node:
            self.parent[node] = self.find(self.parent[node])
        return self.parent[node]

    def union(self, node1, node2):
        root1 = self.find(node1)
        root2 = self.find(node2)
        if root1 == root2:
            return
        if self.rank[root1] > self.rank[root2]:
            self.parent[root2] = root1
        elif self.rank[root1] < self.rank[root2]:
            self.parent[root1] = root2
        else:
            self.parent[root2] = root1
            self.rank[root1] += 1

def shortest_path(graph: Dict[int, List[Tuple[int, int]]], source: int, target: int) -> Tuple[float, List[int]]:
    if source not in graph or target not in graph:
        return float("inf"), None

    # Union-Find initialization
    uf = UnionFind(max(graph.keys()) + 1)

    # Create a list of edges sorted by weight
    edges = []
    for node, neighbors in graph.items():
        for neighbor, weight in neighbors:
            edges.append((weight, node, neighbor))
    heapq.heapify(edges)

    # Build the MST
    mst = []
    while edges:
        weight, u, v = heapq.heappop(edges)
        if uf.find(u) != uf.find(v):
            uf.union(u, v)
            mst.append((u, v, weight))

    # Check if the target node is reachable from the source node
    if uf.find(source) != uf.find(target):
        return float("inf"), None

    # Compute the shortest path
    distance = 0
    path = [source]
    while path[-1] != target:
        for weight, u, v in mst:
            if u == path[-1]:
                distance += weight
                path.append(v)
                break
    return distance, path

