def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rank[rootX] < rank[rootY]:
        parent[rootX] = rootY
    elif rank[rootX] > rank[rootY]:
        parent[rootY] = rootX
    else:
        parent[rootY] = rootX
        rank[rootX] += 1

def kruskal(graph, source, target):
    parent = {}
    rank = {}
    edges = []
    for node in graph:
        parent[node] = node
        rank[node] = 0
        for neighbour, weight in graph[node]:
            edge = (weight, node, neighbour)
            edges.append(edge)
    edges.sort()
    mst = []
    for weight, node, neighbour in edges:
        if find(parent, node) != find(parent, neighbour):
            union(parent, rank, node, neighbour)
            mst.append((node, neighbour, weight))
    distance = float('inf')
    path = []
    for edge in mst:
        node, neighbour, weight = edge
        if neighbour == target:
            distance = weight
            path = [source] + [node] + [neighbour]
            break
    if distance == float('inf'):
        return (float('inf'), None)
    else:
        return (distance, path)
