def shortest_path(graph, source, target):
    # A* Search Algorithm
    def astar_search(graph, source, target):
        # Priority queue to hold (priority, node, path, remaining_cost)
        priority_queue = [(0, source, [], 0)]
        # Set to keep track of visited nodes
        visited = set()
        # Dictionary to keep track of the best estimated cost to the target from each node
        g = {node: float('inf') for node in graph}
        g[source] = 0
        # Dictionary to keep track of the best path to each node
        f = {node: float('inf') for node in graph}
        f[source] = h(source, target)

        while priority_queue:
            _, node, path, cost = heapq.heappop(priority_queue)

            if node == target:
                return cost, path

            if node in visited:
                continue

            visited.add(node)

            for neighbor, weight in graph[node]:
                new_cost = cost + weight

                if new_cost < g[neighbor]:
                    g[neighbor] = new_cost
                    f[neighbor] = g[neighbor] + h(neighbor, target)
                    heapq.heappush(priority_queue, (f[neighbor], neighbor, path + [neighbor], new_cost))

        return float('inf'), None

    def h(node, target):
        # Simple heuristic: Manhattan distance (assumes grid-based graph for simplicity)
        return abs(node[0] - target[0]) + abs(node[1] - target[1])

